  "Like Button (optimistic + rollback)": [
    {
      "label": "a click updates the heart and count immediately",
      "steps": [
        {
          "click": {
            "role": "button",
            "name": "Like"
          }
        },
        {
          "expect": {
            "role": "button",
            "name": "Like"
          },
          "attr": "aria-pressed",
          "equals": "true"
        },
        {
          "expectText": "42"
        },
        {
          "expectText": "Requests sent: 1"
        },
        {
          "wait": 800
        },
        {
          "expect": {
            "role": "button",
            "name": "Like"
          },
          "attr": "aria-pressed",
          "equals": "true"
        },
        {
          "expectText": "42"
        }
      ]
    },
    {
      "label": "a failed request rolls back and shows an error",
      "steps": [
        {
          "click": {
            "role": "button",
            "name": "Make the next request fail"
          }
        },
        {
          "click": {
            "role": "button",
            "name": "Like"
          }
        },
        {
          "expect": {
            "role": "alert",
            "text": "undone"
          }
        },
        {
          "expect": {
            "role": "button",
            "name": "Like"
          },
          "attr": "aria-pressed",
          "equals": "false"
        },
        {
          "expectText": "41"
        }
      ]
    },
    {
      "label": "like, unlike, like quickly sends one request and ends liked",
      "steps": [
        {
          "click": {
            "role": "button",
            "name": "Like"
          }
        },
        {
          "click": {
            "role": "button",
            "name": "Like"
          }
        },
        {
          "click": {
            "role": "button",
            "name": "Like"
          }
        },
        {
          "expect": {
            "role": "button",
            "name": "Like"
          },
          "attr": "aria-pressed",
          "equals": "true"
        },
        {
          "wait": 1300
        },
        {
          "expectText": "Requests sent: 1"
        },
        {
          "expect": {
            "role": "button",
            "name": "Like"
          },
          "attr": "aria-pressed",
          "equals": "true"
        },
        {
          "expectText": "42"
        }
      ]
    },
    {
      "label": "like, unlike quickly sends a second request and ends unliked",
      "steps": [
        {
          "click": {
            "role": "button",
            "name": "Like"
          }
        },
        {
          "click": {
            "role": "button",
            "name": "Like"
          }
        },
        {
          "expectText": "Requests sent: 2"
        },
        {
          "wait": 700
        },
        {
          "expect": {
            "role": "button",
            "name": "Like"
          },
          "attr": "aria-pressed",
          "equals": "false"
        },
        {
          "expectText": "41"
        },
        {
          "expectText": "Requests sent: 2"
        }
      ]
    }
  ],
